const coins = [
  { id: 'bitcoin', symbol: 'BTC', name: 'Bitcoin', warningAbsPct: 3, criticalAbsPct: 6 },
  { id: 'ethereum', symbol: 'ETH', name: 'Ethereum', warningAbsPct: 4, criticalAbsPct: 8 },
  { id: 'solana', symbol: 'SOL', name: 'Solana', warningAbsPct: 5, criticalAbsPct: 10 },
];

const currency = 'usd';
const response = items[0].json;
const checkedAt = new Date().toISOString();

return coins.map((coin) => {
  const record = response[coin.id] || {};
  const price = record[currency];
  const change = record[`${currency}_24h_change`];

  if (price === undefined || change === undefined) {
    return {
      json: {
        checked_at: checkedAt,
        currency,
        id: coin.id,
        symbol: coin.symbol,
        name: coin.name,
        price: null,
        change_24h_pct: null,
        direction: 'unknown',
        severity: 'warning',
        alert: true,
        threshold_hit: null,
        reason: 'missing_price_or_change',
      },
    };
  }

  const changeValue = Number(change.toFixed(2));
  const absChange = Math.abs(changeValue);
  let severity = 'normal';
  let thresholdHit = null;

  if (absChange >= coin.criticalAbsPct) {
    severity = 'critical';
    thresholdHit = coin.criticalAbsPct;
  } else if (absChange >= coin.warningAbsPct) {
    severity = 'warning';
    thresholdHit = coin.warningAbsPct;
  }

  return {
    json: {
      checked_at: checkedAt,
      currency,
      id: coin.id,
      symbol: coin.symbol,
      name: coin.name,
      price: Number(Number(price).toFixed(2)),
      change_24h_pct: changeValue,
      direction: changeValue >= 0 ? 'up' : 'down',
      severity,
      alert: severity !== 'normal',
      threshold_hit: thresholdHit,
      source_last_updated_at: record.last_updated_at || null,
    },
  };
});

const severityRank = { normal: 0, warning: 1, critical: 2 };
const alerts = items.map((item) => item.json);
const highest = alerts.reduce((current, item) => {
  return severityRank[item.severity] > severityRank[current] ? item.severity : current;
}, 'normal');

const lines = alerts.map((item) => {
  const sign = item.change_24h_pct > 0 ? '+' : '';
  return `${item.symbol}: ${sign}${item.change_24h_pct}% ${item.direction} at ${item.price} ${item.currency.toUpperCase()} (${item.severity})`;
});

return [
  {
    json: {
      generated_at: new Date().toISOString(),
      currency: alerts[0]?.currency || 'usd',
      alert_count: alerts.length,
      highest_severity: highest,
      alerts,
      message: `Crypto market alert: ${alerts.length} asset(s) crossed threshold.\n${lines.join('\n')}`,
    },
  },
];

return items.map((item) => ({
  json: {
    ...item.json,
    audit_status: 'alert_payload_ready',
    audit_note: 'Alert payload was built successfully. Enable Send Alert Webhook after configuring ALERT_WEBHOOK_URL.',
  },
}));

return [
  {
    json: {
      generated_at: new Date().toISOString(),
      status: 'no_alert',
      message: 'No configured crypto threshold was crossed in this run.',
      assets_checked: items.map((item) => ({
        symbol: item.json.symbol,
        price: item.json.price,
        change_24h_pct: item.json.change_24h_pct,
        severity: item.json.severity,
      })),
    },
  },
];
